#include <bits/stdc++.h>
using namespace std;
typedef unsigned __int128 u128;

string toString(u128 v) {
    if (v == 0) return "0";
    string s;
    while (v) {
        s += char('0' + (int)(v % 10));
        v /= 10;
    }
    reverse(s.begin(), s.end());
    return s;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; i++) {
        long long v;
        scanf("%lld", &v);
        prefix[i + 1] = prefix[i] + v;
    }
    // counts never exceed 2^(n-1) <= 2^99, so 128-bit unsigned integers are exact
    vector<vector<u128>> rise(n, vector<u128>(n + 1, 0)), fall(n, vector<u128>(n + 1, 0));
    for (int i = 1; i < n; i++)
        for (int j = i + 1; j <= n; j++) {
            long long newSum = prefix[j] - prefix[i], newSize = j - i;
            u128 up = 0, down = 0;
            for (int h = 0; h < i; h++) {
                long long previousCross = (prefix[i] - prefix[h]) * newSize;
                long long newCross = newSum * (i - h);
                if (previousCross < newCross) up += rise[h][i] + (h == 0 ? 1 : 0);
                else if (previousCross > newCross) down += rise[h][i] + fall[h][i];
            }
            rise[i][j] = up;
            fall[i][j] = down;
        }
    u128 answer = 0;
    for (int i = 0; i < n; i++) answer += fall[i][n];
    printf("%s\n", toString(answer).c_str());
}

import java.io.*;
import java.math.BigInteger;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nextLong();
        // counts reach 2^99, so they are exact big integers
        BigInteger[][] rise = new BigInteger[n][n + 1], fall = new BigInteger[n][n + 1];
        for (int i = 0; i < n; i++)
            for (int j = 0; j <= n; j++) rise[i][j] = fall[i][j] = BigInteger.ZERO;
        for (int i = 1; i < n; i++)
            for (int j = i + 1; j <= n; j++) {
                long newSum = prefix[j] - prefix[i], newSize = j - i;
                BigInteger up = BigInteger.ZERO, down = BigInteger.ZERO;
                for (int h = 0; h < i; h++) {
                    long previousCross = (prefix[i] - prefix[h]) * newSize;
                    long newCross = newSum * (i - h);
                    if (previousCross < newCross) {
                        up = up.add(rise[h][i]);
                        if (h == 0) up = up.add(BigInteger.ONE);
                    } else if (previousCross > newCross) {
                        down = down.add(rise[h][i]).add(fall[h][i]);
                    }
                }
                rise[i][j] = up;
                fall[i][j] = down;
            }
        BigInteger answer = BigInteger.ZERO;
        for (int i = 0; i < n; i++) answer = answer.add(fall[i][n]);
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"math/big"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	prefix := make([]int64, n+1)
	for i := 0; i < n; i++ {
		prefix[i+1] = prefix[i] + nextInt()
	}
	// counts reach 2^99, so they are exact big integers
	rise := make([][]*big.Int, n)
	fall := make([][]*big.Int, n)
	for i := range rise {
		rise[i] = make([]*big.Int, n+1)
		fall[i] = make([]*big.Int, n+1)
		for j := range rise[i] {
			rise[i][j] = new(big.Int)
			fall[i][j] = new(big.Int)
		}
	}
	one := big.NewInt(1)
	for i := 1; i < n; i++ {
		for j := i + 1; j <= n; j++ {
			newSum, newSize := prefix[j]-prefix[i], int64(j-i)
			up, down := rise[i][j], fall[i][j]
			for h := 0; h < i; h++ {
				previousCross := (prefix[i] - prefix[h]) * newSize
				newCross := newSum * int64(i-h)
				if previousCross < newCross {
					up.Add(up, rise[h][i])
					if h == 0 {
						up.Add(up, one)
					}
				} else if previousCross > newCross {
					down.Add(down, rise[h][i])
					down.Add(down, fall[h][i])
				}
			}
		}
	}
	answer := new(big.Int)
	for i := 0; i < n; i++ {
		answer.Add(answer, fall[i][n])
	}
	fmt.Println(answer.String())
}
